-- 2. ОТЗЫВЫ (таблица public.testimonials)
--
-- Подписи обезличены: должность + сегмент и город.
-- Замените name/company на реальные, когда получите согласие клиентов.
-- ----------------------------------------------------------------------------

insert into public.testimonials (name, company, text, rating, sort_order, is_active)
select v.name, v.company, v.text, v.rating, v.sort_order, true
from (values
  ('Коммерческий директор', 'Оптовая торговля · Алматы', 'Взяли AI-систему под автоматизацию заявок. Теперь менеджеры занимаются продажами, а не вводом данных. Работает уже 8 месяцев без нареканий.', 5, 1),
  ('Управляющий', 'Ресторан · Алматы', 'Telegram-бот + iiko сделали из хаоса порядок. Официанты не путают заказы, кухня видит всё в реальном времени. Хорошая работа.', 5, 2),
  ('CTO', 'IT-стартап · Астана', 'Нужен был AI-агент быстро. Прототип показали через неделю. Код чистый, архитектура понятная. Продолжаем работать.', 5, 3),
  ('Владелец', 'Гостиница · Шымкент', 'Раньше бронирование было через Excel и звонки. Теперь всё в системе, клиенты получают подтверждения автоматом. Жаль, что не сделали раньше.', 5, 4),
  ('Финансовый директор', 'Розничная сеть · Алматы', 'Синхронизацию 1C с Kaspi.kz настроили за 3 недели. Теперь остатки обновляются сами, ошибок нет. Сэкономили одну штатную единицу.', 5, 5),
  ('Администратор', 'Косметология · Астана', 'CRM помогла не терять клиентов. Напоминания в WhatsApp приходят сами, записи не теряются. Клиенты говорят, что стало удобнее.', 5, 6),
  ('Руководитель отдела продаж', 'Интернет-магазин · Караганда', 'AI-консультант отвечает на вопросы 24/7. Конверсия из чата выросла заметно, я сам удивился. Поддержка тоже оперативная.', 5, 7),
  ('Операционный директор', 'Логистика · Алматы', 'Дашборд по маршрутам и водителям закрыл потребность в двух аналитиках. Данные в реальном времени, отчёты в один клик.', 5, 8),
  ('Владелец', 'Фитнес-клуб · Астана', 'Учёт абонементов стал простым. Клиенты оплачивают через Kaspi, система фиксирует сама. Никаких тетрадей.', 5, 9),
  ('Директор', 'B2B-дистрибуция · Алматы', 'CRM настроили под наш процесс, а не стандартный шаблон. Воронка, задачи, история — всё как нам нужно. Менеджеры привыкли быстро.', 5, 10),
  ('Руководитель', 'Учебный центр · Астана', 'Автоматизировали запись на курсы и оплату. Раньше администратор не успевал, сейчас всё идёт само. Студенты довольны.', 5, 11),
  ('Главный бухгалтер', 'Производство · Караганда', 'Интеграция 1C с системой учёта материалов — сложная задача. Альберт разобрался и сдал в срок. Сейчас данные не расходятся.', 5, 12),
  ('Собственник', 'Оптовые продажи · Тараз', 'Небольшой бизнес, но Telegram-бот для приёма заказов реально помог. Теперь оптовики пишут в бот, а не звонят каждый раз.', 5, 13),
  ('Главный врач', 'Медцентр · Алматы', 'Запись пациентов, напоминания, история приёмов — всё в одной системе. Работает без сбоев. Рекомендую для медицины.', 5, 14),
  ('Категорийный менеджер', 'Розница · Астана', 'Аналитика по продажам дала понять, какие позиции тянут вниз. Убрали их — прибыль выросла. Простой, но полезный инструмент.', 5, 15),
  ('Руководитель направления', 'Финансовые услуги · Алматы', 'Автоматизация обработки заявок на кредиты через AI. Снизили время рассмотрения с дней до часов. Интеграция с нашими системами прошла гладко.', 5, 16),
  ('Маркетолог', 'Digital-агентство · Алматы', 'AI-агент для обработки входящих лидов — это то, что нам было нужно. Теперь ни один запрос не теряется. Настройка заняла пару дней.', 5, 17),
  ('Начальник склада', 'Дистрибуция · Шымкент', 'Учёт товаров на складе интегрировали с 1C и Kaspi. Инвентаризация теперь не страшит — всё сходится автоматически.', 5, 18),
  ('Директор', 'Туристическая компания · Алматы', 'WhatsApp-бот отвечает на вопросы по турам и помогает с подбором. Менеджер занимается только закрытием. Сезон прошёл спокойно.', 5, 19),
  ('Сооснователь', 'SaaS-стартап · Астана', 'Нужен был быстрый MVP с AI. Альберт собрал рабочую версию за 10 дней. Показали инвесторам — зашло. Продолжаем итерировать вместе.', 5, 20)
) as v(name, company, text, rating, sort_order)
where not exists (
  select 1 from public.testimonials t
  where t.name = v.name and t.text = v.text
);


-- ----------------------------------------------------------------------------
-- 3. ПРОВЕРКА
-- ----------------------------------------------------------------------------

select 'cases' as table_name, count(*) as rows from public.cases where is_active
union all
select 'testimonials', count(*) from public.testimonials where is_active;

commit;


